expect -c "
set timeout 10
spawn ssh -o StrictHostKeyChecking=no -o PubkeyAuthentication=no -p 25068 root@connect.westd.seetacloud.com echo OK
expect {
    \"*assword:\" {
        send \"9koPyDBQi2Fm\r\"
        expect {
            \"OK\" { puts \"SUCCESS\" }
            \"denied\" { puts \"DENIED\" }
            timeout { puts \"TIMEOUT\" }
        }
    }
    timeout { puts \"NO_PROMPT\" }
}
" 2>&1
